package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
/** Baseline probe only; no production claim. Map delete uses a distinct UI path. */
final class MapVertexConfirmationChecks {
 final MapAndroidChecks m;final GeometryConfirmationChecks g;final VertexRotationChecks p;final ManagerVisualChecks v;final ManagerRotationChecks r;
 MapVertexConfirmationChecks(MapAndroidChecks m){this.m=m;g=new GeometryConfirmationChecks(m);p=g.p;v=g.v;r=g.r;}
 boolean present(){final boolean[] b={false};m.runOnMainSync(()->{View root=m.activeDialogRoot();b[0]=g.contains(root,"Удалить выбранную вершину из текущего ввода?")&&v.button(root,"Удалить")!=null&&v.button(root,"Отмена")!=null;});return b[0];}
 JSONObject layout()throws Exception{final JSONObject o=new JSONObject();m.runOnMainSync(()->{try{View decor=m.activity.getWindow().getDecorView();android.graphics.Rect frame=new android.graphics.Rect();decor.getWindowVisibleDisplayFrame(frame);o.put("activity",m.activity.getClass().getName());o.put("destroyed",m.activity.isDestroyed());o.put("orientation",m.activity.getResources().getConfiguration().orientation);o.put("frame",frame.flattenToString());o.put("decorWidth",decor.getWidth());o.put("decorHeight",decor.getHeight());o.put("mapMode",m.editorField("mapMode"));View body=(View)m.editorField("body");o.put("bodyWidth",body.getWidth());o.put("bodyHeight",body.getHeight());o.put("canvasPresent",m.editorField("mapCanvas")!=null);if(m.editorField("mapCanvas")!=null){View surface=m.mapSurface();android.graphics.Rect visible=new android.graphics.Rect();boolean shown=surface.getGlobalVisibleRect(visible);o.put("surfaceWidth",surface.getWidth());o.put("surfaceHeight",surface.getHeight());o.put("surfaceLaidOut",surface.isLaidOut());o.put("surfaceShown",surface.isShown());o.put("surfaceVisible",shown);o.put("surfaceBounds",visible.flattenToString());o.put("interactiveThreshold",surface.getWidth()>80&&surface.getHeight()>80);}o.put("focusedRoot",m.activeDialogRoot().getClass().getName());}catch(Exception e){throw new RuntimeException(e);}});return o;}
 void settledMapLayout()throws Exception{long end=System.currentTimeMillis()+15000;String previous="";int stable=0;JSONObject current=null;while(System.currentTimeMillis()<end){m.waitForIdleSync();current=layout();String dimensions=current.toString();if(current.optBoolean("canvasPresent")&&current.optBoolean("mapMode")&&!current.getBoolean("destroyed")&&current.optBoolean("surfaceLaidOut")){if(dimensions.equals(previous)){if(++stable>=3){v.emit("MAP_VERTEX_LAYOUT "+current.toString());return;}}else stable=0;}previous=dimensions;Thread.sleep(100);}v.emit("MAP_VERTEX_LAYOUT_TIMEOUT "+String.valueOf(current));throw new AssertionError("map layout did not settle after actual recreation");}
 void snapshot(String stage)throws Exception{JSONObject o=new JSONObject();o.put("stage",stage);o.put("layout",layout());o.put("present",present());o.put("key",g.key());o.put("token",m.editorField("expected"));o.put("main",m.editorText());o.put("selected",m.vertexState()==null?-1:m.call(m.vertexState(),"selected",new Class[]{}));o.put("viewport",m.editorField("mapCanvas")==null?JSONObject.NULL:Arrays.toString((double[])m.call(m.editorField("mapCanvas"),"viewport",new Class[]{})));final JSONArray text=new JSONArray();m.runOnMainSync(()->{try{v.inspect(m.activeDialogRoot(),text);}catch(Exception e){throw new RuntimeException(e);}});o.put("texts",text);m.capture("mvisual-map-vertex-confirm-"+stage);v.emit("MAP_VERTEX_CONFIRM_VISUAL "+o.toString());}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());long id=-1;try{id=g.fixture(store,false);Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));g.open(id,false);m.click("Редактировать на карте");m.mapEditorReady();float[] point=m.vertexPixel(1);m.mapTouch(point[0],point[1],point[0],point[1],false,false);m.check((Integer)m.call(m.vertexState(),"selected",new Class[]{})==1,"real map touch selects middle vertex before baseline");String main=m.editorText(),token=(String)m.editorField("expected");m.check(main.equals(g.main)&&g.key().equals("0")&&m.activity.getResources().getConfiguration().orientation==1,"settled portrait and exact dirty map input/address fixture");v.emit("MAP_VERTEX_CONFIRM_PRECONDITION portrait=true selected=1 key=0 mainExact=true");double[] originalViewport=((double[])m.call(m.editorField("mapCanvas"),"viewport",new Class[]{})).clone();boolean all=true,interactive=true,viewportSame=true;for(int direction:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){m.clickDescription("Удалить выбранную вершину");m.check(present(),"map confirmation fixture");m.click("Отмена");m.check(m.editorText().equals(main),"map Cancel before rotation never deletes a vertex");g.unchanged(store,id,xml,assets);m.clickDescription("Удалить выбранную вершину");snapshot("before-"+(direction==UiAutomation.ROTATION_FREEZE_90?"land":"return"));Activity old=m.activity;p.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"map confirmation Activity actually destroyed/recreated");v.emit("MAP_VERTEX_RECREATE direction="+direction+" old="+System.identityHashCode(old)+" current="+System.identityHashCode(m.activity)+" oldDestroyed="+old.isDestroyed());try{settledMapLayout();}finally{snapshot("after-"+(direction==UiAutomation.ROTATION_FREEZE_90?"land":"return"));}boolean restored=present();all&=restored;interactive&=layout().getBoolean("interactiveThreshold");double[] actualViewport=(double[])m.call(m.editorField("mapCanvas"),"viewport",new Class[]{});for(int axis=0;axis<3;axis++)viewportSame&=!Double.isNaN(actualViewport[axis])&&!Double.isInfinite(actualViewport[axis])&&Math.abs(originalViewport[axis]-actualViewport[axis])<1e-9;v.emit("MAP_VERTEX_VIEWPORT expected="+Arrays.toString(originalViewport)+" actual="+Arrays.toString(actualViewport)+" same="+viewportSame);m.check(m.editorText().equals(main)&&token.equals(m.editorField("expected"))&&g.key().equals("0")&&(Integer)m.call(m.vertexState(),"selected",new Class[]{})==1,"map raw/selected/address/token exact after real rotation");g.unchanged(store,id,xml,assets);if(restored)m.click("Отмена");v.emit("MAP_VERTEX_CONFIRM_BASELINE direction="+direction+" restored="+restored+" raw/selected/token/KML/assets unchanged=true");}m.check(m.requests.get()==requests,"map confirmation baseline uses no online tiles");m.check(interactive,"original map surface >80x80 interaction threshold after both recreations; see measured layout");m.check(viewportSame,"original map centre and zoom retained after both actual recreations");m.check(all,"map vertex deletion confirmation survives both actual Activity recreations");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);if(id>0)m.call(store,"remove",new Class[]{long.class},id);m.call(store,"close",new Class[]{});}}
}
